/**
 * A labelled corpus of group email a student actually receives around introductions, used to tune and pin
 * `readIntroduction` / `detectIntroduction` (pipeline/introductions.ts).
 *
 * Every message is read as ingest reads it: quoted history stripped, signature split off. The student is Alex
 * Rivera (alex.rivera@cornell.edu). People are named by roster key on the From, To and CC lines; `me` is the
 * student. `prior` says the thread already holds a recorded introduction (a later sync of the same thread).
 *
 * Labels:
 * - `introduction`: the sender introduces the student to `introduced` (people on the To or CC line).
 * - `intro_reply`: a message inside an introduction thread (thanks for the intro, moving the introducer to bcc,
 *   a reply-all with times, a nudge from the introducer), which must not open a new introduction.
 * - `none`: anything else (meeting wording, a CC without an introduction, machine mail, a scheduler hand-off).
 *
 * `INTRO_TRAIN` is what the classifier was tuned on; `INTRO_HOLDOUT` is a fifth of the corpus written after tuning
 * froze and measured once blind. Each hold-out round that fell short of the bar was folded into the tuning set and
 * a fresh round written (ROUND_ONE to ROUND_ELEVEN record each round's blind score); see INTRO_HOLDOUT for the last.
 */

import { readIntroduction } from '../../pipeline/introductions';
import { splitSignature, stripQuotedReply } from '../../text/email';
