export type IntroKind = 'introduction' | 'intro_reply' | 'none';

export interface IntroCase {
  id: string;
  from: string;
  to: string[];
  cc?: string[];
  subject: string;
  body: string;
  /** sent by the student */
  outbound?: boolean;
  /** machine mail (auto-reply, calendar notice) as ingest flags it */
  automated?: boolean;
  /** the thread already holds this introduction */
  prior?: { by: string; introduced: string[] };
  expect: { kind: IntroKind; introduced?: string[] };
}

const intro = (...introduced: string[]) => ({ kind: 'introduction' as const, introduced });
const reply = { kind: 'intro_reply' as const };
const none = { kind: 'none' as const };

